/* Hack for adjusting position of bottom-fixed elements to prevent being cropped out by Safari's browser bar */
@media screen  and (max-device-width: 480px) and (orientation: portrait) { 

	/*html, body {
  		height: 100% !important;
  		margin: 0 !important;
  		padding: 0 !important;
	}*/

  	div.container article.page .fixed-position-container-top.polyfill-sticky{
        height: 100dvh !important;
      	transition: height 250ms cubic-bezier(0.785, 0.135, 0.150, 0.860);
  	}
    div.container article.page:first-of-type .fixed-position-container-top.polyfill-sticky{
        height: 105lvh !important;
  	}

}

/********** Overrides default transparent-on-hover effect */
.isdesktop a:hover .rmwidget.widget-shape:not(.has-onhover-animation),
.no-isdesktop a:active .rmwidget.widget-shape {
	opacity: 1 !important;
}

/********** Ensures nav links occupy  all of the available width */

/*div.above-pages-container .rmwidget.widget-text-v3:has(a.maglink){
